param([string]$Revision='0.1.0-dev.1')
$ErrorActionPreference='Stop';$jar="target/madlava-agent-$Revision.jar";if(!(Test-Path $jar)){throw "Missing $jar"};$java=Join-Path $env:JAVA_HOME 'bin\jar.exe';$entries=& $java tf $jar;if($entries -notcontains 'com/madlava/agent/MadLavaAgent.class'){throw 'Premain class absent'};if($entries -match '^org/apache/spark/|^org/junit/'){throw 'Forbidden dependency in agent'};$manifest=& $java xf $jar 'META-INF/MANIFEST.MF';try{$text=Get-Content -Raw 'META-INF/MANIFEST.MF';if($text -notmatch 'Premain-Class: com.madlava.agent.MadLavaAgent'){throw 'Premain-Class absent'};if($text -notmatch 'Can-Retransform-Classes: false'){throw 'Retransform manifest mismatch'}}finally{Remove-Item -LiteralPath META-INF -Recurse -Force};Write-Output 'Agent archive: PASS'
